"""
Screen 4 — AppVM selection.
User picks which trust-domain VMs to provision.
Defaults: personal, work, banking checked.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw

from .base import BasePage
from ..state import WizardState
from typing import Callable


# (vm_id, display_name, subtitle, default_checked)
APPVM_DEFS = [
    ("personal",    "Personal",    "Web browsing, email, social media — medium trust",           True),
    ("work",        "Work",        "Office documents, meetings, internal tools — high trust",    True),
    ("banking",     "Banking",     "Financial sites only — maximum isolation",                   True),
    ("development", "Development", "Compilers, containers, local servers — dev trust",           False),
    ("disposable",  "Disposable",  "Ephemeral VM wiped completely on every shutdown",            False),
    ("media",       "Media",       "Streaming, video playback, downloaded media files",          False),
]


class AppVMScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="AppVMs", tag="appvms")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "Choose your AppVMs",
                "Select which isolated VM environments to provision. "
                "Each VM handles a specific trust domain. More can be added later "
                "from virt-manager.",
            )
        )

        group = Adw.PreferencesGroup()
        group.set_title("Available environments")
        group.set_description(
            "sys-net and sys-firewall are always provisioned automatically."
        )
        self._body.append(group)

        self._checks: dict[str, Gtk.CheckButton] = {}

        for vm_id, name, subtitle, default in APPVM_DEFS:
            row = Adw.ActionRow()
            row.set_title(name)
            row.set_subtitle(subtitle)
            row.set_activatable(True)

            check = Gtk.CheckButton()
            check.set_active(default)
            row.add_prefix(check)
            row.set_activatable_widget(check)
            check.connect("toggled", self._on_toggled, vm_id)

            group.add(row)
            self._checks[vm_id] = check

            # Set defaults into state
            if default:
                if vm_id not in self.state.selected_appvms:
                    self.state.selected_appvms.append(vm_id)

        # Gaming VM row — only shown if GPU passthrough was enabled
        self._gaming_row = Adw.ActionRow()
        self._gaming_row.set_title("Gaming VM")
        self._gaming_row.set_subtitle("Dedicated gaming environment with GPU passthrough")
        self._gaming_check = Gtk.CheckButton()
        self._gaming_check.set_active(True)
        self._gaming_row.add_prefix(self._gaming_check)
        self._gaming_row.set_activatable_widget(self._gaming_check)
        self._gaming_row.set_activatable(True)
        self._gaming_check.connect("toggled", self._on_gaming_toggled)
        group.add(self._gaming_row)

        self._body.append(
            self.make_button_row(
                back_label="Back",
                back_cb=lambda: self.go_to("back"),
                next_label="Review",
                next_cb=lambda: self.go_to("review"),
            )
        )

    def on_enter(self):
        # Show/hide gaming row based on GPU passthrough state
        self._gaming_row.set_visible(self.state.gpu_passthrough)
        if self.state.gpu_passthrough:
            if "gaming-vm" not in self.state.selected_appvms:
                self.state.selected_appvms.append("gaming-vm")

    def _on_toggled(self, check: Gtk.CheckButton, vm_id: str):
        if check.get_active():
            if vm_id not in self.state.selected_appvms:
                self.state.selected_appvms.append(vm_id)
        else:
            if vm_id in self.state.selected_appvms:
                self.state.selected_appvms.remove(vm_id)

    def _on_gaming_toggled(self, check: Gtk.CheckButton):
        if check.get_active():
            if "gaming-vm" not in self.state.selected_appvms:
                self.state.selected_appvms.append("gaming-vm")
        else:
            if "gaming-vm" in self.state.selected_appvms:
                self.state.selected_appvms.remove("gaming-vm")
